--- /dev/null
+++ b/src/main/java/hotel/notifications/GovernanceNotifier.java
@@ -0,0 +1,40 @@
+package hotel.notifications;
+
+import hotel.documents.TextFormat;
+import hotel.messages.EmailSender;
+import hotel.reservations.Reservation;
+import hotel.reservations.ReservationListener;
+
+/** Tells housekeeping which rooms to prepare and which ones were freed. */
+public final class GovernanceNotifier implements ReservationListener {
+
+    private final EmailSender emailSender;
+    private final String address;
+
+    public GovernanceNotifier(EmailSender emailSender, String address) {
+        this.emailSender = emailSender;
+        this.address = address;
+    }
+
+    @Override
+    public void onConfirmed(Reservation reservation) {
+        emailSender.send(
+                address,
+                "Reserva confirmada - quarto " + reservation.roomNumber(),
+                "Entrada: " + TextFormat.date(reservation.checkIn()) + "\n"
+                        + "Saída: " + TextFormat.date(reservation.checkOut()) + "\n"
+                        + "Hóspedes: " + reservation.guests() + "\n");
+    }
+
+    @Override
+    public void onCancelled(Reservation reservation, boolean wasConfirmed) {
+        if (!wasConfirmed) {
+            return;
+        }
+        emailSender.send(
+                address,
+                "Reserva cancelada - quarto " + reservation.roomNumber(),
+                "Datas liberadas: de " + TextFormat.date(reservation.checkIn())
+                        + " a " + TextFormat.date(reservation.checkOut()) + "\n");
+    }
+}
diff --git a/src/main/java/hotel/reservations/ReservationListener.java b/src/main/java/hotel/reservations/ReservationListener.java
new file mode 100644
index 0000000..78d70a2
--- /dev/null
+++ b/src/main/java/hotel/reservations/ReservationListener.java
@@ -0,0 +1,19 @@
+package hotel.reservations;
+
+/**
+ * Someone who wants to know what happens to reservations. Implement only the events of interest and
+ * register the listener where the service is built.
+ */
+public interface ReservationListener {
+
+    /** The guest paid and the reservation is now confirmed. */
+    default void onConfirmed(Reservation reservation) {
+    }
+
+    /**
+     * The reservation was cancelled. {@code wasConfirmed} tells whether it had been paid for (confirmed)
+     * before; the refund is in {@link Reservation#refund()}.
+     */
+    default void onCancelled(Reservation reservation, boolean wasConfirmed) {
+    }
+}
