     1	package hotel.reservations;
     2	
     3	import hotel.documents.ReservationReceipt;
     4	import hotel.messages.EmailSender;
     5	import hotel.rooms.Room;
     6	import hotel.rooms.Rooms;
     7	import java.math.BigDecimal;
     8	import java.util.List;
     9	
    10	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
    11	public final class ReservationService {
    12	
    13	    static final String HOTEL_NAME = "Pousada Maré Alta";
    14	
    15	    private final Rooms rooms;
    16	    private final ReservationStore store;
    17	    private final PriceCalculator priceCalculator;
    18	    private final EmailSender emailSender;
    19	    private final List<ReservationListener> listeners;
    20	
    21	    public ReservationService(
    22	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
    23	        this(rooms, store, priceCalculator, emailSender, List.of());
    24	    }
    25	
    26	    public ReservationService(
    27	            Rooms rooms,
    28	            ReservationStore store,
    29	            PriceCalculator priceCalculator,
    30	            EmailSender emailSender,
    31	            List<ReservationListener> listeners) {
    32	        this.listeners = List.copyOf(listeners);
    33	        this.rooms = rooms;
    34	        this.store = store;
    35	        this.priceCalculator = priceCalculator;
    36	        this.emailSender = emailSender;
    37	    }
    38	
    39	    public synchronized Reservation create(NewReservation request) {
    40	        if (!request.checkOut().isAfter(request.checkIn())) {
    41	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
    42	        }
    43	        if (request.guests() < 1) {
    44	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
    45	        }
    46	        Room room = rooms.find(request.roomNumber())
    47	                .orElseThrow(() -> new HotelException(
    48	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    49	        if (request.guests() > room.capacity()) {
    50	            throw new HotelException(
    51	                    ErrorCode.CAPACITY_EXCEEDED,
    52	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
    53	        }
    54	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
    55	            throw new HotelException(
    56	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
    57	        }
    58	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
    59	        return store.add(request, price);
    60	    }
    61	
    62	    public Reservation find(long reservationId) {
    63	        return store.find(reservationId)
    64	                .orElseThrow(() -> new HotelException(
    65	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
    66	    }
    67	
    68	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
    69	    public synchronized Reservation confirm(long reservationId) {
    70	        Reservation reservation = find(reservationId);
    71	        if (reservation.status() != ReservationStatus.PENDING) {
    72	            throw notAllowed(reservation, "confirm");
    73	        }
    74	        reservation.confirmPayment();
    75	        store.update(reservation);
    76	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
    77	        emailSender.send(
    78	                reservation.guest().email(),
    79	                "Reserva confirmada - " + HOTEL_NAME,
    80	                confirmationEmailBody(reservation, receipt));
    81	        listeners.forEach(listener -> listener.onConfirmed(reservation));
    82	        return reservation;
    83	    }
    84	
    85	    /**
    86	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
    87	     * reservation was never paid, so nothing comes back).
    88	     */
    89	    public synchronized Reservation cancel(long reservationId) {
    90	        Reservation reservation = find(reservationId);
    91	        if (reservation.status() != ReservationStatus.PENDING
    92	                && reservation.status() != ReservationStatus.CONFIRMED) {
    93	            throw notAllowed(reservation, "cancel");
    94	        }
    95	        boolean wasConfirmed = reservation.status() == ReservationStatus.CONFIRMED;
    96	        BigDecimal refund = switch (reservation.ratePlan()) {
    97	            case STANDARD -> reservation.amountPaid();
    98	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
    99	        };
   100	        reservation.cancel(refund);
   101	        store.update(reservation);
   102	        listeners.forEach(listener -> listener.onCancelled(reservation, wasConfirmed));
   103	        return reservation;
   104	    }
   105	
   106	    public synchronized Reservation checkIn(long reservationId) {
   107	        Reservation reservation = find(reservationId);
   108	        if (reservation.status() != ReservationStatus.CONFIRMED) {
   109	            throw notAllowed(reservation, "check in");
   110	        }
   111	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
   112	        store.update(reservation);
   113	        return reservation;
   114	    }
   115	
   116	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
   117	    public synchronized ReservationReceipt checkOut(long reservationId) {
   118	        Reservation reservation = find(reservationId);
   119	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   120	            throw notAllowed(reservation, "check out");
   121	        }
   122	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   123	        store.update(reservation);
   124	        return new ReservationReceipt(reservation, roomOf(reservation));
   125	    }
   126	
   127	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
   128	    public ReservationReceipt receiptCopy(long reservationId) {
   129	        Reservation reservation = find(reservationId);
   130	        if (!reservation.isPaid()) {
   131	            throw notAllowed(reservation, "issue a receipt for");
   132	        }
   133	        return new ReservationReceipt(reservation, roomOf(reservation));
   134	    }
   135	
   136	    private Room roomOf(Reservation reservation) {
   137	        return rooms.find(reservation.roomNumber()).orElseThrow();
   138	    }
   139	
   140	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
   141	        return "Olá, " + reservation.guest().name() + "!\n\n"
   142	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
   143	                + receipt.text() + "\n"
   144	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   145	                + "Até breve!\n";
   146	    }
   147	
   148	    private static HotelException notAllowed(Reservation reservation, String operation) {
   149	        return new HotelException(
   150	                ErrorCode.OPERATION_NOT_ALLOWED,
   151	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
   152	    }
   153	}
